-- Domain 14: Finance: Expenses & Payables | functions
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 315
CREATE FUNCTION public.acct_spend_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_bank_accounts%ROWTYPE;
BEGIN
  SELECT * INTO r FROM acct_bank_accounts WHERE id = NEW.bank_account_id AND tenant_id = NEW.tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment account must be one of this company''s bank or card registers'; END IF;
  NEW.entity_id := coalesce(NEW.entity_id, r.entity_id);
  NEW.currency := coalesce(NEW.currency, r.currency);
  IF NEW.txn_kind IN ('cc_charge','cc_credit') AND r.account_kind <> 'credit_card' THEN RAISE EXCEPTION 'Credit card charges/credits need a credit card register'; END IF;
  IF NEW.txn_kind = 'check' AND r.account_kind NOT IN ('checking','savings','money_market') THEN RAISE EXCEPTION 'Checks must be drawn on a bank account'; END IF;
  IF NEW.txn_kind = 'check' THEN
    NEW.payment_method := 'check';
    IF NEW.check_number IS NULL AND NEW.print_status <> 'to_print' THEN
      NEW.check_number := coalesce(r.next_check_number, 1001);
      UPDATE acct_bank_accounts SET next_check_number = NEW.check_number + 1 WHERE id = r.id;
    END IF;
    NEW.ref_no := coalesce(NEW.ref_no, NEW.check_number::text);
    IF NEW.print_status = 'not_applicable' THEN NEW.print_status := 'printed'; END IF;
  END IF;
  IF NEW.payee_vendor_id IS NOT NULL THEN NEW.mailing_address := coalesce(NEW.mailing_address, acct_address_text('vendor', NEW.payee_vendor_id, 'remit_to')); END IF;
  NEW.created_by := coalesce(NEW.created_by, auth.uid());
  RETURN NEW;
END $$;

-- @seq 316
CREATE FUNCTION public.acct_spend_inventory_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE l record; it acct_items%ROWTYPE; v_ref text;
BEGIN
  IF TG_WHEN = 'BEFORE' THEN
    IF NEW.status = 'void' AND OLD.status IS DISTINCT FROM 'void' AND EXISTS (
         SELECT 1 FROM acct_inventory_moves m JOIN acct_inventory_layers y ON y.source_move_id = m.id
          WHERE m.source_type = 'acct_spend_transactions' AND m.source_id = NEW.id AND m.reversed_by_move_id IS NULL AND y.qty_remaining < y.qty_in) THEN
      RAISE EXCEPTION 'Inventory from this purchase has already been sold or used. Record a credit instead of voiding.';
    END IF;
    RETURN NEW;
  END IF;
  v_ref := coalesce(NEW.ref_no, NEW.check_number::text, NEW.txn_kind);
  IF OLD.posted_journal_id IS NULL AND NEW.posted_journal_id IS NOT NULL THEN
    FOR l IN SELECT * FROM acct_spend_lines WHERE spend_id = NEW.id ORDER BY line_no LOOP
      IF NEW.txn_kind = 'cc_credit' THEN
        CONTINUE WHEN l.item_id IS NULL;
        SELECT * INTO it FROM acct_items WHERE id = l.item_id;
        CONTINUE WHEN it.item_type <> 'inventory' OR l.account_id <> it.inventory_asset_account_id;
        PERFORM acct__inv_vendor_return(NEW.tenant_id, NEW.entity_id, l.item_id, l.quantity, l.amount + l.tax_amount, NEW.payment_date,
                                        'acct_spend_transactions', NEW.id, l.id, v_ref);
      ELSE
        PERFORM acct__purchase_line_posted(NEW.tenant_id, NEW.entity_id, 'acct_spend_transactions', NEW.id, l.id, NEW.payment_date, v_ref,
                                           l.item_id, l.account_id, l.quantity, l.amount + l.tax_amount, l.description, NEW.payee_name);
      END IF;
    END LOOP;
  END IF;
  IF NEW.status = 'void' AND OLD.status IS DISTINCT FROM 'void' THEN
    PERFORM acct__inv_reverse_source('acct_spend_transactions', NEW.id, coalesce(NEW.voided_at::date, NEW.payment_date), 'Void ' || v_ref);
    UPDATE acct_fixed_assets SET status = 'retired' WHERE source_doc_type = 'acct_spend_transactions' AND source_doc_id = NEW.id AND status = 'draft';
  END IF;
  RETURN NULL;
END $$;

-- @seq 317
CREATE FUNCTION public.acct_spend_line_after_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid := coalesce(NEW.spend_id, OLD.spend_id);
BEGIN
  UPDATE acct_spend_transactions t SET subtotal = s.sub, tax_total = s.tax, total = s.sub + s.tax, updated_at = now()
    FROM (SELECT coalesce(sum(amount),0) sub, coalesce(sum(tax_amount),0) tax FROM acct_spend_lines WHERE spend_id = v) s
   WHERE t.id = v AND t.status = 'draft';
  RETURN NULL;
END $$;

-- @seq 318
CREATE FUNCTION public.acct_spend_line_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s acct_spend_transactions%ROWTYPE; i acct_items%ROWTYPE;
BEGIN
  SELECT * INTO s FROM acct_spend_transactions WHERE id = NEW.spend_id;
  IF s.status <> 'draft' THEN RAISE EXCEPTION 'Transaction is %; void it and re-enter', s.status; END IF;
  NEW.tenant_id := s.tenant_id;
  IF NEW.line_no IS NULL THEN SELECT coalesce(max(line_no),0)+1 INTO NEW.line_no FROM acct_spend_lines WHERE spend_id = NEW.spend_id; END IF;
  IF NEW.item_id IS NOT NULL THEN
    SELECT * INTO i FROM acct_items WHERE id = NEW.item_id AND tenant_id = s.tenant_id;
    NEW.account_id := coalesce(NEW.account_id, CASE WHEN i.item_type='inventory' THEN i.inventory_asset_account_id ELSE i.expense_account_id END);
    NEW.description := coalesce(NEW.description, i.purchase_description, i.name);
    IF NEW.rate = 0 THEN NEW.rate := coalesce(i.purchase_cost, 0); END IF;
    NEW.amount := round(NEW.quantity * NEW.rate, 2);
  ELSIF NEW.amount = 0 AND NEW.rate <> 0 THEN NEW.amount := round(NEW.quantity * NEW.rate, 2);
  END IF;
  IF NEW.account_id IS NULL THEN RAISE EXCEPTION 'Choose a category for line %', NEW.line_no; END IF;
  IF EXISTS (SELECT 1 FROM acct_chart_of_accounts WHERE id = NEW.account_id AND (is_control_account OR NOT is_posting_allowed OR tenant_id <> s.tenant_id)) THEN
    RAISE EXCEPTION 'Line % cannot post to a control/header account or another company''s account', NEW.line_no; END IF;
  RETURN NEW;
END $$;

-- @seq 380
CREATE FUNCTION public.convert_purchase_order_to_bill(p_tenant_id uuid, p_po_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_po        purchase_orders%rowtype;
  v_bill_id   uuid;
  v_bill_num  text;
  v_items     jsonb := '[]'::jsonb;
  v_item      purchase_order_items%rowtype;
begin
  select * into v_po from purchase_orders where id = p_po_id and tenant_id = p_tenant_id;
  if not found then raise exception 'Purchase order not found'; end if;
  if v_po.converted_bill_id is not null then
    return v_po.converted_bill_id;
  end if;

  v_bill_num := replace(v_po.number, 'PO-', 'BILL-');

  for v_item in select * from purchase_order_items where purchase_order_id = p_po_id loop
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'product_id', v_item.product_id,
      'inventory_item_id', v_item.inventory_item_id,
      'account_id', v_item.account_id,
      'tax_id', v_item.tax_id,
      'description', v_item.description,
      'quantity', v_item.quantity,
      'unit_price', v_item.unit_price,
      'discount', v_item.discount,
      'position', v_item.position
    ));
  end loop;

  v_bill_id := create_bill(
    p_tenant_id := p_tenant_id,
    p_number := v_bill_num,
    p_vendor_id := v_po.vendor_id,
    p_issue_date := v_po.issue_date,
    p_due_date := coalesce(v_po.expected_date, v_po.issue_date + 30),
    p_currency := v_po.currency,
    p_items := v_items,
    p_notes := v_po.notes,
    p_ap_account_id := null
  );

  update purchase_orders
     set converted_bill_id = v_bill_id, status = 'closed', updated_at = now()
   where id = p_po_id;

  return v_bill_id;
end;
$$;

-- @seq 382
CREATE FUNCTION public.create_bill(p_tenant_id uuid, p_number text, p_vendor_id text, p_issue_date date, p_due_date date DEFAULT NULL::date, p_currency text DEFAULT 'USD'::text, p_items jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text, p_ap_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_bill_id     uuid;
  v_ap_acct     uuid := p_ap_account_id;
  v_subtotal    numeric(18,4) := 0;
  v_tax_total   numeric(18,4) := 0;
  v_total       numeric(18,4) := 0;
  v_item        jsonb;
  v_line_amt    numeric(18,4);
  v_tax_rate    numeric(6,4);
  v_lines       jsonb := '[]'::jsonb;
  v_journal_id  uuid;
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'No bill items provided';
  end if;

  if v_ap_acct is null then
    select id into v_ap_acct from chart_of_accounts
     where tenant_id = p_tenant_id and code = '2000' limit 1;
  end if;
  if v_ap_acct is null then
    raise exception 'No Accounts Payable account found. Seed standard chart of accounts.';
  end if;

  insert into bills (tenant_id, number, vendor_id, issue_date, due_date, currency, status,
                     subtotal, tax_total, total, ap_account_id, notes)
  values (p_tenant_id, p_number, p_vendor_id, p_issue_date, p_due_date, p_currency, 'received',
          0, 0, 0, v_ap_acct, p_notes)
  returning id into v_bill_id;

  for v_item in select jsonb_array_elements(p_items) loop
    v_line_amt := coalesce((v_item->>'quantity')::numeric, 1) * coalesce((v_item->>'unit_price')::numeric, 0)
                  - coalesce((v_item->>'discount')::numeric, 0);
    v_subtotal := v_subtotal + v_line_amt;

    v_tax_rate := 0;
    if v_item ? 'tax_id' and (v_item->>'tax_id') is not null then
      select rate into v_tax_rate from taxes where id = (v_item->>'tax_id')::uuid;
    end if;
    v_tax_total := v_tax_total + (v_line_amt * v_tax_rate);

    insert into bill_items (bill_id, product_id, inventory_item_id, account_id, tax_id,
                            description, quantity, unit_price, discount, position)
    values (v_bill_id,
            nullif(v_item->>'product_id','')::text,
            nullif(v_item->>'inventory_item_id','')::text,
            (v_item->>'account_id')::uuid,
            nullif(v_item->>'tax_id','')::uuid,
            v_item->>'description',
            coalesce((v_item->>'quantity')::numeric, 1),
            coalesce((v_item->>'unit_price')::numeric, 0),
            coalesce((v_item->>'discount')::numeric, 0),
            coalesce((v_item->>'position')::int, 0));

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'account_id', (v_item->>'account_id')::uuid,
      'debit', v_line_amt, 'credit', 0,
      'description', coalesce(v_item->>'description', 'Bill ' || p_number)
    ));

    if v_item ? 'inventory_item_id' and (v_item->>'inventory_item_id') is not null then
      perform apply_stock_movement(
        p_tenant_id := p_tenant_id,
        p_inventory_item_id := (v_item->>'inventory_item_id')::text,
        p_date := p_issue_date,
        p_type := 'purchase',
        p_quantity := coalesce((v_item->>'quantity')::numeric, 1),
        p_unit_cost := coalesce((v_item->>'unit_price')::numeric, 0),
        p_source := 'bill',
        p_source_id := v_bill_id::text,
        p_reference := p_number
      );
    end if;
  end loop;

  v_total := v_subtotal + v_tax_total;

  v_lines := v_lines || jsonb_build_array(jsonb_build_object(
    'account_id', v_ap_acct,
    'debit', 0, 'credit', v_total,
    'description', 'AP — ' || p_number
  ));

  if v_tax_total > 0 then
    declare
      v_tax_acct uuid;
    begin
      select id into v_tax_acct from chart_of_accounts
       where tenant_id = p_tenant_id and code = '2100' limit 1;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object(
        'account_id', v_tax_acct,
        'debit', v_tax_total, 'credit', 0,
        'description', 'Sales tax recoverable — ' || p_number
      ));
    end;
  end if;

  v_journal_id := post_journal(
    p_tenant_id := p_tenant_id,
    p_entry_date := p_issue_date,
    p_lines := v_lines,
    p_memo := 'Bill ' || p_number || ' received',
    p_reference := p_number,
    p_source := 'bill',
    p_source_id := v_bill_id::text,
    p_currency := p_currency
  );

  update bills
     set subtotal = v_subtotal,
         tax_total = v_tax_total,
         total = v_total,
         journal_id = v_journal_id
   where id = v_bill_id;

  return v_bill_id;
end;
$$;

